import csv
import io
import re


_NUMERIC = re.compile(r"[+-]?(?:[0-9]+(?:[.,][0-9]*)?|[.,][0-9]+)(?:[eE][+-]?[0-9]+)?")


def parse_csv(raw_csv: str):
    expected_width = 4
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
    ))

    def is_blank(record):
        return not record or (len(record) == 1 and not record[0].strip())

    def is_numeric(value):
        return _NUMERIC.fullmatch(value.strip()) is not None

    header_index = next(
        (i for i, record in enumerate(records) if not is_blank(record)),
        None,
    )
    if header_index is None:
        return {"columns": [], "rows": []}

    # Skip a narrow textual preamble only when a full header and numeric
    # data follow it. Otherwise retain the first nonblank record as the header.
    candidate = header_index
    while candidate < len(records):
        record = records[candidate]
        if not is_blank(record) and (
            len(record) >= expected_width or any(is_numeric(v) for v in record)
        ):
            break
        candidate += 1

    if header_index < candidate < len(records):
        record = records[candidate]
        if len(record) == expected_width and all(
            value.strip() and not is_numeric(value) for value in record
        ):
            following = next(
                (row for row in records[candidate + 1:] if not is_blank(row)),
                None,
            )
            if following is not None and any(is_numeric(v) for v in following):
                header_index = candidate

    columns = records[header_index][:]
    data = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, data), default=0))

    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        base = f"column_{position}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in data],
    }
